export function makeReviewItem(fields: Partial<ReviewItem> & { id: number }): ReviewItem {
  return {
    ...base,
    review_reasons: [],
    review_details: null,
    status: "open",
    resolved_at: null,
    resolution_note: null,
    ...fields,
  };
}

